do $$
declare
  n integer;
begin
  select count(*) into n from semantic_private.presumed_terms;
  raise notice '0381: % terms in the dictionary', n;
  select count(*) into n from semantic_private.presumed_terms
   where english_label is not null;
  raise notice '0381: % carry an English label', n;
  select count(*) into n from semantic_private.presumed_terms
   where canonical_term_id is not null;
  raise notice '0381: % defer to a canonical', n;
  select count(*) into n from semantic_private.presumed_term_relations;
  raise notice '0381: % relations recorded', n;
  select count(*) into n from semantic_private.presumed_terms
   where proposed_parent_concept_id is not null;
  raise notice '0381: % carry a proposed parent', n;
  -- **The thin rows, said out loud.** 65% of this dictionary rested on a
  -- single mention when nothing promoted; the owner's 2026-08-24 direction
  -- makes discovery mint, so the number is now the one to watch.
  select count(*) into n from semantic_private.presumed_terms
   where entry_support = 1;
  raise notice '0381: % rest on a single library entry', n;
  select count(*) into n from semantic_private.presumed_terms
   where family_support_share is not null and family_support_share < 0.2;
  raise notice '0381: % are a minority reading of their own label', n;
end;
$$;

-- **Every load ends with the resolver — 0340's own rule, honoured by the
-- emitter rather than remembered by an operator.** The first load shipped
-- with 1,475 rows naming concepts the catalogue already published and none
-- linked, because resolution was a step somebody had to think of. Exact
-- identity, kind agreement, ambiguity refused; the counts land in the log.
do $$
declare
  r record;
begin
  select * into r from semantic_private.resolve_presumed_terms_to_catalogue();
  raise notice
    '0381: resolver linked %, refused % ambiguous, % kind-mismatched',
    r.linked, r.ambiguous, r.kind_mismatch;
end;
$$;

